import http from 'node:http';
import { randomUUID } from 'node:crypto';
import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.dirname(fileURLToPath(import.meta.url));
const dataDir = path.join(root, 'data');
const dataFile = path.join(dataDir, 'books.json');
const port = Number(process.env.PORT) || 3000;
let writeQueue = Promise.resolve();

async function readBooks() {
  try {
    const data = await readFile(dataFile, 'utf8');
    const books = JSON.parse(data);
    if (!Array.isArray(books)) throw new Error('Book data must be a JSON array.');
    return books;
  } catch (error) {
    if (error.code === 'ENOENT') return [];
    throw error;
  }
}

function updateBooks(change) {
  const operation = writeQueue.then(async () => {
    const books = await readBooks();
    const result = await change(books);
    const tempFile = `${dataFile}.${randomUUID()}.tmp`;
    await writeFile(tempFile, `${JSON.stringify(books, null, 2)}\n`, 'utf8');
    await rename(tempFile, dataFile);
    return result;
  });
  writeQueue = operation.catch(() => {});
  return operation;
}

function sendJson(response, status, data) {
  response.writeHead(status, {
    'Content-Type': 'application/json; charset=utf-8',
    'Cache-Control': 'no-store',
  });
  response.end(JSON.stringify(data));
}

async function readBody(request) {
  let body = '';
  for await (const chunk of request) {
    body += chunk;
    if (body.length > 1_000_000) throw Object.assign(new Error('Request body is too large.'), { status: 413 });
  }
  try {
    return JSON.parse(body || '{}');
  } catch {
    throw Object.assign(new Error('Please send valid JSON.'), { status: 400 });
  }
}

function cleanText(value, limit) {
  return typeof value === 'string' ? value.trim().slice(0, limit) : '';
}

async function handleApi(request, response, url) {
  if (url.pathname === '/api/books' && request.method === 'GET') {
    return sendJson(response, 200, await readBooks());
  }

  if (url.pathname === '/api/books' && request.method === 'POST') {
    const body = await readBody(request);
    const title = cleanText(body.title, 160);
    const author = cleanText(body.author, 120);
    const notes = cleanText(body.notes, 10_000);
    if (!title || !author) {
      return sendJson(response, 400, { error: 'A title and author are required.' });
    }
    const book = {
      id: randomUUID(),
      title,
      author,
      notes,
      status: 'reading',
      addedAt: new Date().toISOString(),
      finishedAt: null,
    };
    await updateBooks((books) => books.unshift(book));
    return sendJson(response, 201, book);
  }

  const match = url.pathname.match(/^\/api\/books\/([\w-]+)$/);
  if (!match) return sendJson(response, 404, { error: 'Not found.' });
  const [, id] = match;

  if (request.method === 'GET') {
    const book = (await readBooks()).find((item) => item.id === id);
    return book ? sendJson(response, 200, book) : sendJson(response, 404, { error: 'Book not found.' });
  }

  if (request.method === 'PATCH') {
    const body = await readBody(request);
    if (body.status !== 'finished') {
      return sendJson(response, 400, { error: 'The only supported update is marking a book finished.' });
    }
    let updated;
    await updateBooks((books) => {
      const index = books.findIndex((item) => item.id === id);
      if (index < 0) return;
      books[index] = { ...books[index], status: 'finished', finishedAt: new Date().toISOString() };
      updated = books[index];
    });
    return updated ? sendJson(response, 200, updated) : sendJson(response, 404, { error: 'Book not found.' });
  }

  return sendJson(response, 405, { error: 'Method not allowed.' });
}

const assets = {
  '/styles.css': ['styles.css', 'text/css; charset=utf-8'],
  '/app.js': ['app.js', 'text/javascript; charset=utf-8'],
};

const server = http.createServer(async (request, response) => {
  try {
    const url = new URL(request.url, `http://${request.headers.host || 'localhost'}`);
    if (url.pathname.startsWith('/api/')) {
      await handleApi(request, response, url);
      return;
    }
    const asset = assets[url.pathname];
    const file = asset ? path.join(root, asset[0]) : path.join(root, 'index.html');
    const content = await readFile(file);
    response.writeHead(200, {
      'Content-Type': asset?.[1] || 'text/html; charset=utf-8',
      'Cache-Control': asset ? 'public, max-age=3600' : 'no-cache',
    });
    response.end(content);
  } catch (error) {
    if (response.headersSent) return response.destroy();
    const status = error.status || 500;
    sendJson(response, status, { error: status === 500 ? 'Something went wrong.' : error.message });
  }
});

